export function normalizeBrandId(raw?: string | null): string {
  const s = String(raw || '').trim().toLowerCase()
  if (!s) return 'other'
  if (BRAND_LOGOS[s]) return s
  if (ALIASES[s]) return ALIASES[s]
  // fuzzy contains
  for (const [a, id] of Object.entries(ALIASES)) {
    if (a.length >= 3 && s.includes(a)) return id
  }
  return 'other'
}

export function logoParts(idOrName?: string | null): LogoSvgPart[] {
  const id = normalizeBrandId(idOrName)
  return BRAND_LOGOS[id]?.parts || BRAND_LOGOS.other!.parts
}

export function logoAccent(idOrName?: string | null): string {
  const id = normalizeBrandId(idOrName)
  return BRAND_LOGOS[id]?.accent || BRAND_LOGOS.other!.accent
}

export function isMultiColorLogo(idOrName?: string | null): boolean {
  const parts = logoParts(idOrName)
  const fills = parts.map((p) => p.fill).filter(Boolean)
  return fills.length > 1
}

/** All registry ids (for filters / selectors). */
export function allBrandIds(): string[] {
  return Object.keys(BRAND_LOGOS).sort()
}
